  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''CDCMIRROR_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''CDCMIRROR_APP''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''CDCMIRROR_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''CDCMIRROR_APP'' AND "comment"=''oneshot-source:29_cdc_mirror_cost''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.CDCMIRROR_APP FROM ''@__TARGET__.APP_STAGE/source/feaabad297cc1ade/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:29_cdc_mirror_cost''; ALTER STREAMLIT __TARGET__.CDCMIRROR_APP ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
